/// The `ComputerSystem` schema represents a computer or system instance and the software-visible resources, or items within the data plane, such as memory, CPU, and other devices that it can access.  Details of those resources or subsystems are also linked through this resource.
pub const ComputerSystemCreate = struct {
    /// The OEM extension property.
    ///
    /// This property shall contain the OEM extensions.  All values for properties that this object contains shall conform to the Redfish Specification-described requirements.
    Oem: ?resource.OemUpdate = null,
    /// The links to other resources that are related to this resource.
    ///
    /// This property shall contain links to resources that are related to but are not contained by, or subordinate to, this resource.
    Links: ?LinksUpdate = null,
    /// The user-definable tag that can track this computer system for inventory or other client purposes.
    ///
    /// This property shall contain the system asset tag value.  Modifying this property may modify the `AssetTag` in the containing `Chassis` resource.
    AssetTag: core.Nullable([]const u8) = .absent,
    /// The DNS host name, without any domain information.
    ///
    /// This property shall contain the host name for this system, as reported by the operating system or hypervisor.  A service running in the host operating system typically reports this value to the manager.  Modifying this property may modify the `HostName` in one or more `EthernetInterface` resources contained in this system.
    HostName: core.Nullable([]const u8) = .absent,
    /// The state of the indicator LED, which identifies the system.
    ///
    /// This property shall contain the state of the indicator light, which identifies this system.
    ///
    /// Deprecated in v1_13_0.
    /// This property has been deprecated in favor of the `LocationIndicatorActive` property.
    IndicatorLED: core.Nullable(IndicatorLed) = .absent,
    /// The boot settings for this system.
    ///
    /// This property shall contain the boot settings for this system.
    Boot: ?BootUpdate = null,
    /// The central processors of the system in general detail.
    ///
    /// This property shall describe the central processors for this resource.  Processors described by this property shall be limited to the processors that execute system code, and shall not include processors used for offload functionality.
    ProcessorSummary: ?ProcessorSummaryUpdate = null,
    /// An array of trusted modules in the system.
    ///
    /// This object shall contain an array of objects with properties that describe the trusted modules for this resource.
    ///
    /// Deprecated in v1_19_0.
    /// This property has been deprecated in favor of the `TrustedComponents` property in `Links`.
    TrustedModules: ?[]const TrustedModulesUpdate = null,
    /// The services that this computer system supports.
    ///
    /// This property shall describe services that this computer system supports.
    HostedServices: ?HostedServicesUpdate = null,
    /// The host watchdog timer functionality for this system.
    ///
    /// This object shall contain properties that describe the host watchdog timer functionality for this system.
    HostWatchdogTimer: ?WatchdogTimerUpdate = null,
    /// The desired power state of the system when power is restored after a power loss.
    ///
    /// This property shall indicate the desired power state of the system when power is applied to the system.  The `LastState` value shall return the system to the `PowerState` property value it was in when power was lost.
    PowerRestorePolicy: ?PowerRestorePolicyTypes = null,
    /// An indicator allowing an operator to physically locate this resource.
    ///
    /// This property shall contain the state of the indicator used to physically identify or locate this resource.  A write to this property shall update the value of `IndicatorLED` in this resource, if supported, to reflect the implementation of the locating function.  Modifying this property may modify the `LocationIndicatorActive` in the containing `Chassis` resource.
    LocationIndicatorActive: core.Nullable(bool) = .absent,
    /// This object describes the last boot progress state.
    ///
    /// This object shall contain the last boot progress state and time.
    BootProgress: core.Nullable(BootProgressUpdate) = .absent,
    /// The number of seconds to delay power on after an externally performed power cycle or during a reset.  Zero seconds indicates no delay to power up.
    ///
    /// This property shall contain the number of seconds to delay power on after an externally performed power cycle or during a reset.  The value `0` shall indicate no delay to power on.
    PowerOnDelaySeconds: core.Nullable(core.Decimal) = .absent,
    /// The number of seconds to delay power off during a reset.  Zero seconds indicates no delay to power off.
    ///
    /// This property shall contain the number of seconds to delay power off during a reset.  The value `0` shall indicate no delay to power off.
    PowerOffDelaySeconds: core.Nullable(core.Decimal) = .absent,
    /// The number of seconds to delay power on after a `Reset` action requesting `PowerCycle` or `FullPowerCycle`.  Zero seconds indicates no delay.
    ///
    /// This property shall contain the number of seconds to delay power on after a `Reset` action requesting `PowerCycle` or `FullPowerCycle`.  The value `0` shall indicate no delay to power on.
    PowerCycleDelaySeconds: core.Nullable(core.Decimal) = .absent,
    /// The serial console services that this system provides.
    ///
    /// This property shall contain information about the serial console services of this system.
    SerialConsole: ?HostSerialConsoleUpdate = null,
    /// The information about the graphical console (KVM-IP) service of this system.
    ///
    /// This property shall contain the information about the graphical console (KVM-IP) service of this system.
    GraphicalConsole: ?HostGraphicalConsoleUpdate = null,
    /// The information about the virtual media service of this system.
    ///
    /// This property shall contain the information about the virtual media service of this system.
    VirtualMediaConfig: ?VirtualMediaConfigUpdate = null,
    /// The power mode setting of the computer system.
    ///
    /// This property shall contain the computer system power mode setting.
    PowerMode: core.Nullable(PowerMode) = .absent,
    /// The idle power saver settings of the computer system.
    ///
    /// This property shall contain the idle power saver settings of the computer system.
    IdlePowerSaver: core.Nullable(IdlePowerSaverUpdate) = .absent,
    /// The key management settings of the computer system.
    ///
    /// This property shall contain the key management settings of the computer system.
    KeyManagement: core.Nullable(KeyManagementUpdate) = .absent,
    /// The information about the in-band IPMI service of this system.
    ///
    /// This property shall contain the information about the in-band IPMI service of this system.
    IPMIHostInterface: ?IpmiHostInterfaceUpdate = null,
    /// The information about the virtualization abilities of this system.
    ///
    /// This property shall contain the information about the virtualization abilities of this system.
    Virtualization: ?VirtualizationUpdate = null,

    pub const jsonStringify = core.Payload(@This()).jsonStringify;
};

